-- Fold hd_parts (053) into the one parts store (148). GENERATED by
-- scripts/build-fold-hd-parts-sql.ts on 2026-10-28 from the live tables. Approved Oct 28.
--
-- ENDS IN ROLLBACK. Read the summary table it prints, then change the last line to
-- COMMIT to keep it. Any check that fails raises an error and nothing is applied.
--
-- hd_parts rows ......................... 255
--   folded inside hd_parts by the normalizer 0
--   NEW parts added ...................... 222
--   MERGED into a store part (not added) . 31  (10 via a stripped 37-, 21 exact)
-- fitment rows added .................... 570  (488 for new parts, 82 extracted onto merged store parts)
-- supersessions added ................... 6  (2 held)
-- cross-references added ................ 18
--
-- Every new row: verified = false, confidence NULL, source 'nwi-hd-parts-053'.
-- NOT carried: hd_parts.notes, hd_parts.specs, hd_parts.engine, hd_parts_cross_ref.cross_notes.
-- The store part type is never changed. hd_parts itself is not touched.
--
-- MERGED (hd_parts number = store number; store part type kept):
--   30-00471-20    = 30-00471-20   same type  +4 fitment
--   37-11-9059     = 11-9059       same type
--   30-60143-00    = 30-60143-00   same type
--   37-11-9954     = 11-9954       TYPE KEPT "Filter - fuel/water separator" (hd_parts said "Filter - fuel")  << one of the six held type items - FLAGGED FOR BROCK  +3 fitment
--   30-00463-00    = 30-00463-00   same type
--   78-1000        = 78-1000       same type  +1 fitment
--   37-11-9099     = 11-9099       same type
--   50-00178-27    = 50-00178-27   same type  +2 fitment
--   50-00178-19    = 50-00178-19   same type  +7 fitment
--   50-00178-24    = 50-00178-24   same type  +7 fitment
--   78-1724        = 78-1724       same type  +4 fitment
--   78-689         = 78-689        same type  +2 fitment
--   78-1669        = 78-1669       same type  +4 fitment
--   30-01121-00    = 30-01121-00   same type  +5 fitment
--   30-01090-05    = 30-01090-05   same type
--   78-835         = 78-835        same type  +1 fitment
--   78-1366        = 78-1366       same type  +2 fitment
--   78-1341        = 78-1341       same type  +5 fitment
--   78-700         = 78-700        same type  +4 fitment
--   78-1681        = 78-1681       same type  +2 fitment
--   37-11-9341     = 11-9341       TYPE KEPT "Filter - fuel/water separator" (hd_parts said "Filter - fuel")  << one of the six held type items - FLAGGED FOR BROCK
--   37-61-600      = 61-600        same type
--   37-11-9959     = 11-9959       same type  +6 fitment
--   50-00162-25    = 50-00162-25   same type  +7 fitment
--   37-11-9342     = 11-9342       same type  << one of the six held type items - FLAGGED FOR BROCK
--   78-1736        = 78-1736       same type  +3 fitment
--   37-22-1376     = 22-1376       same type
--   78-1968        = 78-1968       same type  +5 fitment
--   37-11-9300     = 11-9300       same type  +4 fitment
--   37-61-800      = 61-800        same type
--   78-684         = 78-684        same type  +4 fitment
--
-- HELD, NOT LOADED:
--   supersession 37-11-9098 -> 37-11-9341
--   supersession 45-2323 -> 45-2324
--   part 78-0603 (and its 8 fitment rows): differs from store part 78-603 only by a leading zero
--   part 78-0629 (and its 7 fitment rows): differs from store part 78-629 only by a leading zero
--   group model strings on 37-92-8822: T-series; TS-series; MD-series; RD-series
--   group model strings on 37-61-6283: SB-series
--   group model strings on 37-42-2282: SB-series with ETV
--   group model strings on 66-8560: TS-series; KD-series; MD-series; RD-series; TD-series; SL-series
--   group model strings on 66-7636: SB-series; B-series; SL-series; V-series; T-series

BEGIN;

CREATE TEMP TABLE _fold_before ON COMMIT DROP AS
SELECT (SELECT count(*) FROM public.parts) AS parts, (SELECT count(*) FROM public.part_fitment) AS part_fitment,
       (SELECT count(*) FROM public.part_supersession) AS part_supersession, (SELECT count(*) FROM public.part_cross_reference) AS part_cross_reference;

CREATE TEMP TABLE _fold_parts (manufacturer TEXT, part_number TEXT, part_type TEXT, description TEXT) ON COMMIT DROP;

CREATE TEMP TABLE _fold_fitment (manufacturer TEXT, part_number TEXT, unit_model TEXT) ON COMMIT DROP;

CREATE TEMP TABLE _fold_super (manufacturer TEXT, old_number TEXT, new_number TEXT) ON COMMIT DROP;

CREATE TEMP TABLE _fold_cross (manufacturer TEXT, part_number TEXT, brand TEXT, brand_number TEXT) ON COMMIT DROP;

-- Checks BEFORE writing. Any failure stops everything.
DO $$
BEGIN
  IF (SELECT count(*) FROM _fold_parts) <> 222 OR (SELECT count(*) FROM _fold_fitment) <> 570
  OR (SELECT count(*) FROM _fold_super) <> 6 OR (SELECT count(*) FROM _fold_cross) <> 18 THEN
    RAISE EXCEPTION 'fold: staged row counts are not what the plan says';
  END IF;
  IF EXISTS (SELECT 1 FROM _fold_parts f JOIN public.parts p
             ON p.manufacturer = f.manufacturer AND p.part_number_normalized = public.normalize_part_number(f.part_number)) THEN
    RAISE EXCEPTION 'fold: a new part is already in the store - the store changed since this file was built; rebuild it';
  END IF;
  IF EXISTS (SELECT 1 FROM _fold_fitment WHERE NOT public.is_single_model(unit_model)) THEN
    RAISE EXCEPTION 'fold: a fitment model is a group';
  END IF;
  IF EXISTS (SELECT 1 FROM _fold_fitment f WHERE NOT EXISTS (SELECT 1 FROM _fold_parts n WHERE n.manufacturer = f.manufacturer AND n.part_number = f.part_number)
             AND NOT EXISTS (SELECT 1 FROM public.parts p WHERE p.manufacturer = f.manufacturer AND p.part_number_normalized = public.normalize_part_number(f.part_number))) THEN
    RAISE EXCEPTION 'fold: a fitment row names no part';
  END IF;
  IF EXISTS (SELECT 1 FROM _fold_fitment f JOIN public.parts p
             ON p.manufacturer = f.manufacturer AND p.part_number_normalized = public.normalize_part_number(f.part_number)
             JOIN public.part_fitment x ON x.part_id = p.id AND upper(x.unit_model) = upper(f.unit_model)) THEN
    RAISE EXCEPTION 'fold: a fitment row is already in the store';
  END IF;
END $$;

SELECT manufacturer, part_number, part_type, description, NULL, FALSE, 'nwi-hd-parts-053', NULL FROM _fold_parts;

SELECT p.id, f.unit_model, FALSE, 'nwi-hd-parts-053', NULL
  FROM _fold_fitment f
  JOIN public.parts p ON p.manufacturer = f.manufacturer AND p.part_number_normalized = public.normalize_part_number(f.part_number);

SELECT manufacturer, old_number, new_number, NULL, FALSE, 'nwi-hd-parts-053', NULL FROM _fold_super;

SELECT p.id, c.brand, c.brand_number, FALSE, 'nwi-hd-parts-053', NULL
  FROM _fold_cross c
  JOIN public.parts p ON p.manufacturer = c.manufacturer AND p.part_number_normalized = public.normalize_part_number(c.part_number);

-- Checks AFTER writing: every table moved by exactly the planned amount, nothing else.
DO $$
DECLARE b RECORD;
BEGIN
  SELECT * INTO b FROM _fold_before;
  IF (SELECT count(*) FROM public.parts) - b.parts <> 222 THEN RAISE EXCEPTION 'fold: parts did not grow by 222'; END IF;
  IF (SELECT count(*) FROM public.part_fitment) - b.part_fitment <> 570 THEN RAISE EXCEPTION 'fold: part_fitment did not grow by 570'; END IF;
  IF (SELECT count(*) FROM public.part_supersession) - b.part_supersession <> 6 THEN RAISE EXCEPTION 'fold: part_supersession did not grow by 6'; END IF;
  IF (SELECT count(*) FROM public.part_cross_reference) - b.part_cross_reference <> 18 THEN RAISE EXCEPTION 'fold: part_cross_reference did not grow by 18'; END IF;
  IF EXISTS (SELECT 1 FROM public.parts WHERE source = 'nwi-hd-parts-053' AND (verified OR confidence IS NOT NULL OR notes IS NOT NULL)) THEN RAISE EXCEPTION 'fold: a new part is not verified=false / confidence NULL / notes NULL'; END IF;
  IF EXISTS (SELECT 1 FROM public.parts WHERE source = 'nwi-hd-parts-053' AND part_number LIKE '37-%') THEN RAISE EXCEPTION 'fold: a 37- number got in'; END IF;
END $$;

-- What it did (this is the table the SQL editor shows).
SELECT 'parts' AS table_name, b.parts AS before, (SELECT count(*) FROM public.parts) AS after, 222 AS planned FROM _fold_before b
UNION ALL SELECT 'part_fitment', b.part_fitment, (SELECT count(*) FROM public.part_fitment), 570 FROM _fold_before b
UNION ALL SELECT 'part_supersession', b.part_supersession, (SELECT count(*) FROM public.part_supersession), 6 FROM _fold_before b
UNION ALL SELECT 'part_cross_reference', b.part_cross_reference, (SELECT count(*) FROM public.part_cross_reference), 18 FROM _fold_before b;

ROLLBACK;
